/** Array table with service-owned multi-row selection and ordered row operations. */
export function JsonArrayEditor({ document, value }: JsonArrayEditorProps) {
    const snapshot = document.getSnapshot();
    const selectedRows = useMemo(() => new Set(snapshot.selectedRows), [snapshot.selectedRows]);
    const objectTable = useMemo(() => value.length > 0 && value.every(isJsonObject), [value]);
    const columns = useMemo(() => objectTable ? objectColumns(value) : ['values'], [objectTable, value]);
    const tableContext = useMemo<JsonArrayTableContext>(() => ({
        columns,
        document,
        location: snapshot.location,
        objectTable,
        rowCount: value.length,
        selectedRows,
    }), [columns, document, objectTable, selectedRows, snapshot.location, value.length]);
    const fixedHeaderContent = useMemo<TableVirtuosoProps<JsonValue, JsonArrayTableContext>['fixedHeaderContent']>(
        () => () => renderHeader(columns),
        [columns],
    );
    const mutationDisabled = document.readOnly;
    const selectionEmpty = selectedRows.size === 0;
    const handleAdd = () => document.addRow('json-editor');
    const handleDelete = () => document.deleteSelectedRows('json-editor');
    const handleCopy = async () => {
        try {
            await document.copySelectedRows(copyTextToClipboard);
        } catch (error) {
            reportClipboardError(error, 'JSON rows could not be copied');
        }
    };
    const handleCut = async () => {
        try {
            await document.cutSelectedRows(copyTextToClipboard, 'json-editor');
        } catch (error) {
            reportClipboardError(error, 'JSON rows could not be cut');
        }
    };
    const handlePaste = async () => {
        try {
            document.pasteRows(await readTextFromClipboard(), 'json-editor');
        } catch (error) {
            reportClipboardError(error, 'JSON rows could not be pasted');
        }
    };

    return (
        <Box sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}>
            <Box sx={{ alignItems: 'center', borderBottom: 1, borderColor: 'divider', display: 'flex', flexShrink: 0, gap: 1, p: 1 }}>
                <Button disabled={mutationDisabled} onClick={handleAdd} variant="outlined">Add</Button>
                <Button disabled={mutationDisabled || selectionEmpty} onClick={handleDelete} variant="outlined">Delete</Button>
                <Button disabled={selectionEmpty} onClick={handleCopy} variant="outlined">Copy</Button>
                <Button disabled={mutationDisabled || selectionEmpty} onClick={handleCut} variant="outlined">Cut</Button>
                <Button disabled={mutationDisabled} onClick={handlePaste} variant="outlined">Paste</Button>
            </Box>
            <TableVirtuoso
                components={JSON_ARRAY_TABLE_COMPONENTS}
                context={tableContext}
                data={value}
                defaultItemHeight={JSON_ARRAY_ESTIMATED_ROW_HEIGHT}
                fixedHeaderContent={fixedHeaderContent}
                itemContent={renderRow}
                overscan={JSON_ARRAY_OVERSCAN}
                style={{ flex: 1, height: '100%', minHeight: 0, width: '100%' }}
            />
        </Box>
    );
}

import { Table } from '@mui/material';
import type { CSSProperties, ReactNode } from 'react';

interface JsonArrayVirtualTableProps {
    children?: ReactNode;
    context: { rowCount: number };
    style?: CSSProperties;
}

/** MUI table surface used by the virtualized JSON array. */
export function JsonArrayVirtualTable(props: JsonArrayVirtualTableProps) {
    const { children, context, style } = props;

    return (
        <Table
            aria-label="JSON array"
            aria-rowcount={context.rowCount + 1}
            size="small"
            stickyHeader
            style={style}
        >
            {children}
        </Table>
    );
}

import { TableHead } from '@mui/material';
import { forwardRef, type CSSProperties, type ReactNode } from 'react';

interface JsonArrayVirtualTableHeadProps {
    children?: ReactNode;
    context: unknown;
    style?: CSSProperties;
}

/** Supplies MUI's header context while retaining Virtuoso's sticky positioning. */
export const JsonArrayVirtualTableHead = forwardRef<HTMLTableSectionElement, JsonArrayVirtualTableHeadProps>(
    function JsonArrayVirtualTableHead(props, ref) {
        const { children, style } = props;

        return <TableHead ref={ref} style={style}>{children}</TableHead>;
    },
);

import { Box, Button, Typography } from '@mui/material';
import { useCallback, useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import type { JsonDataDocument } from '../../services/json/json_data_document';
import { isJsonPrimitive, type JsonValue } from '../../services/json/json_types';
import { JsonScalarEditor } from './json_scalar_editor';

const DEFAULT_FIELD_NAME_WIDTH = 180;
const DEFAULT_OBJECT_EDITOR_WIDTH = 600;
const FIELD_NAME_KEYBOARD_STEP = 24;
const MIN_FIELD_NAME_WIDTH = 120;
const MIN_VALUE_WIDTH = 160;
const SPLITTER_WIDTH = 6;

interface JsonObjectEditorProps {
    document: JsonDataDocument;
    value: { [key: string]: JsonValue };
}

function maximumFieldNameWidth(containerWidth: number) {
    return Math.max(MIN_FIELD_NAME_WIDTH, containerWidth - MIN_VALUE_WIDTH - SPLITTER_WIDTH);
}

function clampFieldNameWidth(width: number, containerWidth: number) {
    return Math.min(Math.max(width, MIN_FIELD_NAME_WIDTH), maximumFieldNameWidth(containerWidth));
}

/** Object properties in resizable field-name and value columns with immutable names. */
export function JsonObjectEditor({ document, value }: JsonObjectEditorProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const [fieldNameWidth, setFieldNameWidth] = useState(DEFAULT_FIELD_NAME_WIDTH);
    const [fieldNameMaxWidth, setFieldNameMaxWidth] = useState(maximumFieldNameWidth(DEFAULT_OBJECT_EDITOR_WIDTH));
    const [isResizing, setIsResizing] = useState(false);
    const getContainerWidth = useCallback(() => {
        const measuredWidth = containerRef.current?.getBoundingClientRect().width ?? 0;
        return measuredWidth > 0 ? measuredWidth : DEFAULT_OBJECT_EDITOR_WIDTH;
    }, []);
    const resizeToPointer = useCallback((clientX: number) => {
        const bounds = containerRef.current?.getBoundingClientRect();
        if (!bounds) return;
        setFieldNameMaxWidth(maximumFieldNameWidth(bounds.width));
        setFieldNameWidth(clampFieldNameWidth(clientX - bounds.left, bounds.width));
    }, []);
    const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
        event.preventDefault();
        setIsResizing(true);
        event.currentTarget.setPointerCapture?.(event.pointerId);
    };
    const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
        if (isResizing) resizeToPointer(event.clientX);
    };
    const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
        if (!isResizing) return;
        resizeToPointer(event.clientX);
        setIsResizing(false);
        if (event.currentTarget.hasPointerCapture?.(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    };
    const handleLostPointerCapture = () => setIsResizing(false);
    const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        const containerWidth = getContainerWidth();
        setFieldNameMaxWidth(maximumFieldNameWidth(containerWidth));
        const widthsByKey: Record<string, number> = {
            ArrowLeft: fieldNameWidth - FIELD_NAME_KEYBOARD_STEP,
            ArrowRight: fieldNameWidth + FIELD_NAME_KEYBOARD_STEP,
            End: maximumFieldNameWidth(containerWidth),
            Home: MIN_FIELD_NAME_WIDTH,
        };
        const nextWidth = widthsByKey[event.key];
        if (nextWidth === undefined) return;
        event.preventDefault();
        setFieldNameWidth(clampFieldNameWidth(nextWidth, containerWidth));
    };
    const fieldEntries = Object.entries(value);

    return (
        <Box
            aria-label="Object fields"
            ref={containerRef}
            role="group"
            sx={{
                alignItems: 'center',
                display: 'grid',
                gap: 1.5,
                gridTemplateColumns: `${fieldNameWidth}px ${SPLITTER_WIDTH}px minmax(0, 1fr)`,
                p: 2,
            }}
        >
            <Box
                aria-label="Resize field name column"
                aria-orientation="vertical"
                aria-valuemax={fieldNameMaxWidth}
                aria-valuemin={MIN_FIELD_NAME_WIDTH}
                aria-valuenow={Math.round(fieldNameWidth)}
                onKeyDown={handleKeyDown}
                onLostPointerCapture={handleLostPointerCapture}
                onPointerCancel={handlePointerUp}
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
                role="separator"
                sx={{
                    alignSelf: 'stretch',
                    bgcolor: isResizing ? 'primary.main' : 'divider',
                    cursor: 'col-resize',
                    gridColumn: 2,
                    gridRow: `1 / span ${Math.max(fieldEntries.length, 1)}`,
                    touchAction: 'none',
                    '&:hover, &:focus-visible': { bgcolor: 'primary.main' },
                }}
                tabIndex={0}
            />
            {fieldEntries.map(([key, fieldValue], index) => {
                const handleOpen = () => document.drillInto(key);
                const location = [...document.getSnapshot().location, key];
                const row = index + 1;

                return (
                    <Box key={key} sx={{ display: 'contents' }}>
                        <Typography color="text.secondary" sx={{ gridColumn: 1, gridRow: row }} variant="caption">{key}</Typography>
                        <Box sx={{ gridColumn: 3, gridRow: row, minWidth: 0 }}>
                            {isJsonPrimitive(fieldValue) ? (
                                <JsonScalarEditor
                                    accessibleName={key}
                                    document={document}
                                    location={location}
                                    value={fieldValue}
                                />
                            ) : (
                                <Button onClick={handleOpen} variant="outlined">
                                    Open {Array.isArray(fieldValue) ? `array (${fieldValue.length})` : 'object'}
                                </Button>
                            )}
                        </Box>
                    </Box>
                );
            })}
        </Box>
    );
}

import { Box, Card, Typography } from '@mui/material';
import { useSyncExternalStore } from 'react';
import type { JsonDataDocument } from '../../services/json/json_data_document';
import { isJsonObject, isJsonPrimitive } from '../../services/json/json_types';
import { JsonArrayEditor } from './json_array_editor';
import { JsonBreadcrumbs } from './json_breadcrumbs';
import { JsonObjectEditor } from './json_object_editor';
import { JsonScalarEditor } from './json_scalar_editor';

interface JsonDataEditorProps {
    document: JsonDataDocument;
}

/** Standalone renderer for one service-owned JSON document. */
export function JsonDataEditor({ document }: JsonDataEditorProps) {
    const snapshot = useSyncExternalStore(document.subscribe, document.getSnapshot, document.getSnapshot);
    const value = document.getValue();
    const handleNavigate = (depth: number) => document.navigateTo(depth);

    return (
        <Box sx={{ display: 'flex', flex: 1, minHeight: 0, minWidth: 0, p: 2 }}>
            <Card
                aria-label="JSON data editor"
                component="section"
                sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0, minWidth: 0 }}
                variant="outlined"
            >
                {snapshot.unavailableReason ? (
                    <Box sx={{ p: 2 }}>
                        <Typography color="error">{snapshot.unavailableReason}</Typography>
                    </Box>
                ) : (
                    <>
                        <JsonBreadcrumbs location={snapshot.location} onNavigate={handleNavigate} path={document.path} />
                        <Box sx={{ borderTop: 1, borderColor: 'divider', display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0, overflow: 'auto' }}>
                            {Array.isArray(value) ? <JsonArrayEditor document={document} value={value} /> : null}
                            {isJsonObject(value) ? <JsonObjectEditor document={document} value={value} /> : null}
                            {isJsonPrimitive(value) ? (
                                <Box sx={{ p: 2 }}>
                                    <JsonScalarEditor
                                        accessibleName="JSON value"
                                        document={document}
                                        location={snapshot.location}
                                        value={value}
                                    />
                                </Box>
                            ) : null}
                        </Box>
                    </>
                )}
            </Card>
        </Box>
    );
}

import { Checkbox, FormControlLabel, TextField } from '@mui/material';
import type { ChangeEvent, KeyboardEvent } from 'react';
import type { JsonDataDocument } from '../../services/json/json_data_document';
import type { JsonLocationSegment, JsonPrimitive } from '../../services/json/json_types';

interface JsonScalarEditorProps {
    accessibleName: string;
    document: JsonDataDocument;
    location: readonly JsonLocationSegment[];
    onChange?: (value: JsonPrimitive) => void;
    value: JsonPrimitive;
}

/** Type-preserving scalar control: edits never change value's JSON type. */
export function JsonScalarEditor(props: JsonScalarEditorProps) {
    const { accessibleName, document, location, onChange, value } = props;
    const updateValue = (nextValue: JsonPrimitive) => {
        if (onChange) {
            onChange(nextValue);
            return;
        }
        document.setValue(location, nextValue, 'json-editor');
    };

    if (typeof value === 'boolean') {
        const handleBooleanChange = (_event: ChangeEvent<HTMLInputElement>, checked: boolean) => {
            updateValue(checked);
        };

        return (
            <FormControlLabel
                disabled={document.readOnly}
                control={<Checkbox checked={value} onChange={handleBooleanChange} slotProps={{ input: { 'aria-label': accessibleName } }} />}
                label={String(value)}
            />
        );
    }

    if (typeof value === 'number') {
        const input = document.getNumberInput(location, value);
        const handleNumberChange = (event: ChangeEvent<HTMLInputElement>) => {
            document.setNumberInput(location, event.target.value);
        };
        const handleNumberBlur = () => {
            document.commitNumberInput(location, 'json-editor');
        };
        const handleNumberKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
            if (event.key === 'Enter') {
                document.commitNumberInput(location, 'json-editor');
                return;
            }
            if (event.key === 'Escape') document.resetNumberInput(location);
        };

        return (
            <TextField
                disabled={document.readOnly}
                error={input.invalid}
                helperText={input.invalid ? 'Enter a valid JSON number' : undefined}
                onBlur={handleNumberBlur}
                onChange={handleNumberChange}
                onKeyDown={handleNumberKeyDown}
                size="small"
                slotProps={{ htmlInput: { 'aria-label': accessibleName, inputMode: 'decimal' } }}
                value={input.text}
            />
        );
    }

    if (value === null) {
        return (
            <TextField
                size="small"
                slotProps={{ htmlInput: { 'aria-label': accessibleName, readOnly: true } }}
                value="null"
            />
        );
    }

    const handleStringChange = (event: ChangeEvent<HTMLInputElement>) => {
        updateValue(event.target.value);
    };

    return (
        <TextField
            disabled={document.readOnly}
            onChange={handleStringChange}
            size="small"
            slotProps={{ htmlInput: { 'aria-label': accessibleName } }}
            value={value}
        />
    );
}

