8	    document: JsonDataDocument;
9	    location: readonly JsonLocationSegment[];
10	    onChange?: (value: JsonPrimitive) => void;
11	    value: JsonPrimitive;
12	}
13	
14	/** Type-preserving scalar control: edits never change value's JSON type. */
15	export function JsonScalarEditor(props: JsonScalarEditorProps) {
16	    const { accessibleName, document, location, onChange, value } = props;
17	    const updateValue = (nextValue: JsonPrimitive) => {
18	        if (onChange) {
19	            onChange(nextValue);
20	            return;
21	        }
22	        document.setValue(location, nextValue, 'json-editor');
23	    };
24	
25	    if (typeof value === 'boolean') {
26	        const handleBooleanChange = (_event: ChangeEvent<HTMLInputElement>, checked: boolean) => {
27	            updateValue(checked);
28	        };
29	
30	        return (
31	            <FormControlLabel
32	                disabled={document.readOnly}
33	                control={<Checkbox checked={value} onChange={handleBooleanChange} slotProps={{ input: { 'aria-label': accessibleName } }} />}
34	                label={String(value)}
35	            />
36	        );
37	    }
38	
39	    if (typeof value === 'number') {
40	        const input = document.getNumberInput(location, value);
41	        const handleNumberChange = (event: ChangeEvent<HTMLInputElement>) => {
42	            document.setNumberInput(location, event.target.value);
43	        };
44	        const handleNumberBlur = () => {
45	            document.commitNumberInput(location, 'json-editor');
46	        };
47	        const handleNumberKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
48	            if (event.key === 'Enter') {
49	                document.commitNumberInput(location, 'json-editor');
50	                return;
51	            }
52	            if (event.key === 'Escape') document.resetNumberInput(location);
53	        };
54	
55	        return (
56	            <TextField
57	                disabled={document.readOnly}
58	                error={input.invalid}
59	                helperText={input.invalid ? 'Enter a valid JSON number' : undefined}
60	                onBlur={handleNumberBlur}
61	                onChange={handleNumberChange}
62	                onKeyDown={handleNumberKeyDown}
63	                size="small"
64	                slotProps={{ htmlInput: { 'aria-label': accessibleName, inputMode: 'decimal' } }}
65	                value={input.text}
66	            />
67	        );
68	    }
69	
70	    if (value === null) {
71	        return (
72	            <TextField
73	                size="small"
74	                slotProps={{ htmlInput: { 'aria-label': accessibleName, readOnly: true } }}
75	                value="null"
76	            />
77	        );
78	    }
79	
80	    const handleStringChange = (event: ChangeEvent<HTMLInputElement>) => {
81	        updateValue(event.target.value);
82	    };
83	
84	    return (
85	        <TextField
86	            disabled={document.readOnly}
87	            onChange={handleStringChange}
88	            size="small"
89	            slotProps={{ htmlInput: { 'aria-label': accessibleName } }}
90	            value={value}
91	        />
92	    );
93	}
